from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Collect all indices where the element is equal to x
        indices = []
        for i, num in enumerate(nums):
            if num == x:
                indices.append(i)

        # Process each query
        result = []
        for q in queries:
            if q <= len(indices):
                result.append(indices[q - 1])
            else:
                result.append(-1)

        return result

import sys
from collections import defaultdict

def main():
    S = sys.stdin.readline().strip()
    groups = defaultdict(list)
    for idx, c in enumerate(S, 1):
        groups[c].append(idx)
    answer = 0
    for c in groups:
        indices = groups[c]
        m = len(indices)
        if m < 2:
            continue
        prefix_sum = 0
        total_sum = 0
        for i in range(m):
            current = indices[i]
            if i == 0:
                prefix_sum = current
            else:
                prefix_sum += current
            if i >= 1:
                term = current * i - (prefix_sum - current)
                total_sum += term
        contribution = total_sum - (m * (m - 1) // 2)
        answer += contribution
    print(answer)

if __name__ == "__main__":
    main()
